using System.Security.Claims;using HastaneRandevuSistemi.Data;using HastaneRandevuSistemi.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace HastaneRandevuSistemi.Controllers;[Authorize(Roles="Doktor")]public class DoctorController:Controller{readonly HospitalContext db;public DoctorController(HospitalContext d)=>db=d;public async Task<IActionResult> Index(){var uid=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var d=await db.Doctors.Include(x=>x.User).Include(x=>x.Branch).Include(x=>x.Appointments).ThenInclude(x=>x.Patient).ThenInclude(x=>x.User).Include(x=>x.MedicalRecords).ThenInclude(x=>x.Patient).ThenInclude(x=>x.User).FirstAsync(x=>x.UserId==uid);return View(d);}[HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> UpdateAppointment(int id,string status){var uid=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var d=await db.Doctors.FirstAsync(x=>x.UserId==uid);var a=await db.Appointments.FirstOrDefaultAsync(x=>x.Id==id&&x.DoctorId==d.Id);if(a!=null){a.Status=status;await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}[HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> AddRecord(int patientId,string diagnosis,string treatment,string prescription){var uid=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var d=await db.Doctors.FirstAsync(x=>x.UserId==uid);db.MedicalRecords.Add(new MedicalRecord{PatientId=patientId,DoctorId=d.Id,Diagnosis=diagnosis??"",Treatment=treatment??"",Prescription=prescription??""});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}}
